    (v_id, $q$Load Time$q$, $q$Load Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Unload Time$q$, $q$Unload Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Cycle Time Factor$q$, $q$Cycle Time Factor$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 7, true),
    (v_id, $q$Rolling Time$q$, $q$Rolling Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$max({Preform Wall} - {Ring Wall}, 0) / {Mandrel Velocity}$q$, 8, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$({Calibration Time} + {Rolling Time} + {Load Time} + {Unload Time}) * {Cycle Time Factor}$q$, 9, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Forging - Ring rolling$q$
  WHERE process_group = $q$Forging$q$ AND operation IN ($q$Ring Rolling$q$);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Forging - Furnace heating$q$, 9, 1),
    ($q$Forging - Hammer energy$q$, 9, 0),
    ($q$Forging - Hammer$q$, 12, 1),
    ($q$Forging - Mechanical press$q$, 4, 1),
    ($q$Forging - Open die force$q$, 11, 0),
    ($q$Forging - Open die press$q$, 10, 1),
    ($q$Forging - Ring preform$q$, 10, 0),
    ($q$Forging - Ring rolling$q$, 9, 1)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Forging$q$) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1054: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
